laboratory.referenceCode:
#include <iostream>

int main() {
    int available{4};
    int requested{6};
    if (available < 0 || available > 100 || requested < 0 || requested > 100) {
        std::cout << "invalid\n";
        return 0;
    }
    int issued = requested <= available ? requested : available;
    available = available - issued;
    std::cout << "issued=" << issued << '\n';
    std::cout << "remaining=" << available << '\n';
    return 0;
}

